-- ========================================================================
--  ENEMY SCANNER & TARGETING (WITH ANCIENT SPIRIT BYPASS)
-- ========================================================================
local function hasLineOfSight(startPos, targetPos, isBoss)
    if isBoss then return true end
    local rayParams = RaycastParams.new()
    rayParams.FilterType = Enum.RaycastFilterType.Blacklist
    rayParams.FilterDescendantsInstances = { LocalPlayer.Character, Workspace:FindFirstChild("enemies") }
    rayParams.IgnoreWater = true

    local dir = (targetPos - (startPos + Vector3.new(0, 2, 0)))
    local result = Workspace:Raycast(startPos + Vector3.new(0, 2, 0), dir, rayParams)

    if result and result.Instance then
        local hitPart = result.Instance
        if hitPart.Transparency >= 0.85 or not hitPart.CanCollide then
            return true
        end
        return false
    end
    return true
end

-- ========================================================================
--  [PRIORITY 0] COMPREHENSIVE BOSS & SUB-BOSS RADAR (SCANS GLOBALLY)
-- ========================================================================
local function isBossTarget(desc, hum, root)
    if not desc or not hum or not root then return false, false end
    local n = desc.Name:lower()

    -- Exclude regular trash mobs
    if n:find("mushroom") or n:find("spear") or n:find("archer") or n:find("spider") or n:find("bat") or n:find("wolf") or n:find("spirit") then
        return false, false
    end

    -- Match any Boss / Sub-Boss name (including Dragon, Tree, Golem, etc.), or any entity with >= 500,000 HP
    local isBoss = (n:find("dragon") ~= nil)
        or (n:find("tree") ~= nil)
        or (n:find("golem") ~= nil)
        or (n:find("ent") ~= nil)
        or (n:find("guardian") ~= nil)
        or (n:find("boss") ~= nil)
        or (n:find("oak") ~= nil)
        or (n:find("elder") ~= nil)
        or (n:find("king") ~= nil)
        or (n:find("lord") ~= nil)
        or (n:find("titan") ~= nil)
        or (n:find("beast") ~= nil)
        or (n:find("ancient") ~= nil)
        or (n:find("champion") ~= nil)
        or (hum.MaxHealth >= 500000)

    if not isBoss then return false, false end

    -- Distinguish Chasm Boss (Ancient Tree in Room 5 across void -> 112s) vs Ground Boss (Dragon, Golem, Ent -> 80s)
    local isTreeChasm = (n:find("ancient tree") ~= nil or (n:find("tree") and n:find("boss")) or n:find("ancient oak"))
        and not n:find("dragon") and not n:find("golem") and not n:find("ent")

    if (root.Position - TREE_CENTER_POS).Magnitude <= 180.0 and (n:find("tree") or n:find("oak")) then
        isTreeChasm = true
    end

    return true, isTreeChasm
end

local function findBossOrTree(currentWp, myPos)
    local checked = {}

    local function inspectObj(desc)
        if not desc or not desc:IsA("Model") or checked[desc] then return nil end
        checked[desc] = true

        for _, p in ipairs(Players:GetPlayers()) do
            if p.Character == desc or p.Name == desc.Name then return nil end
        end

        local hum = desc:FindFirstChildOfClass("Humanoid")
        local root = desc.PrimaryPart or desc:FindFirstChild("HumanoidRootPart") or desc:FindFirstChild("Head") or desc:FindFirstChildOfClass("BasePart")
        if hum and hum.Health > 0 and root then
            local isBoss, isTreeChasm = isBossTarget(desc, hum, root)
            if isBoss then
                local n = desc.Name:lower()
                -- PERMANENT FIX: Do NOT premature-lock Dragon while still clearing Room 6 / corridor (WP < 970)
                if n:find("dragon") and (currentWp and currentWp < 970) and (myPos and myPos.X > -1150.0) then
                    return nil
                end
                return desc, hum, root, isTreeChasm
            end
        end
        return nil
    end

    local dungeon = Workspace:FindFirstChild("dungeon")
    if dungeon then
        for _, room in ipairs(dungeon:GetChildren()) do
            local m, h, r, isT = inspectObj(room)
            if m then return m, h, r, isT end
            for _, desc in ipairs(room:GetDescendants()) do
                local m, h, r, isT = inspectObj(desc)
                if m then return m, h, r, isT end
            end
        end
    end

    local enemies = Workspace:FindFirstChild("enemies")
    if enemies then
        for _, desc in ipairs(enemies:GetChildren()) do
            local m, h, r, isT = inspectObj(desc)
            if m then return m, h, r, isT end
            for _, sub in ipairs(desc:GetDescendants()) do
                local m, h, r, isT = inspectObj(sub)
                if m then return m, h, r, isT end
            end
        end
    end

    for _, desc in ipairs(Workspace:GetChildren()) do
        if desc:IsA("Model") then
            local m, h, r, isT = inspectObj(desc)
            if m then return m, h, r, isT end
            for _, sub in ipairs(desc:GetDescendants()) do
                local m, h, r, isT = inspectObj(sub)
                if m then return m, h, r, isT end
            end
        end
    end

    return nil, nil, nil, false
end

-- ========================================================================
--  [MODULE 5.5] 100% GANG READINESS & DYNAMIC 1:1 REJOIN TRACKER
-- ========================================================================
local function checkGangReadiness(myPos, targetEnemyPos, maxSpread, targetAssemblyDist)
    local gangUsernames = {}
    if Config.CarryUsername and #Config.CarryUsername > 0 then table.insert(gangUsernames, Config.CarryUsername) end
    for _, altName in ipairs(Config.AltUsernames) do
        table.insert(gangUsernames, altName)
    end

    local totalGangInServer = 0
    local livingGangCount = 0
    local assembledGangCount = 0
    local maxAllowedMobDist = (targetAssemblyDist or 105.0) + 12.0

    for _, uName in ipairs(gangUsernames) do
        local p = Players:FindFirstChild(uName)
        if p then
            totalGangInServer = totalGangInServer + 1
            local char = p.Character
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            local hrp = char and char:FindFirstChild("HumanoidRootPart")

            if hum and hum.Health > 0 and hrp then
                livingGangCount = livingGangCount + 1
                local pPos = hrp.Position
                local distToMe = (pPos - myPos).Magnitude
                local distToMob = targetEnemyPos and (pPos - targetEnemyPos).Magnitude or 999.0

                -- Count as assembled if tightly stacked with me (<= 8 studs) OR standing within the room assembly zone
                if distToMe <= 8.0 or (targetEnemyPos and distToMob <= maxAllowedMobDist) then
                    assembledGangCount = assembledGangCount + 1
                end
            end
        end
    end

    if totalGangInServer <= 1 then
        return true, 1, 1, 1
    end

    -- Swarm is ready when all living accounts in server are grouped at the assembly zone
    local isFullGangReady = (livingGangCount >= totalGangInServer) and (assembledGangCount >= totalGangInServer)
    return isFullGangReady, assembledGangCount, livingGangCount, totalGangInServer
end

local function scanLivingEnemies(currentWp)
    local enemies = {}
    local myChar = LocalPlayer.Character
    local myHrp = myChar and myChar:FindFirstChild("HumanoidRootPart")
    if not myHrp then return enemies, nil end

    local myPos = myHrp.Position
    local checked = {}

    local function checkModel(obj)
        if not obj or not obj:IsA("Model") or obj == myChar or checked[obj] then return end
        checked[obj] = true

        for _, p in ipairs(Players:GetPlayers()) do
            if p.Character == obj or p.Name == obj.Name then return end
        end

        local hum = obj:FindFirstChildOfClass("Humanoid")
        local root = obj.PrimaryPart or obj:FindFirstChild("HumanoidRootPart") or obj:FindFirstChild("Head") or obj:FindFirstChildOfClass("BasePart")
        if hum and hum.Health > 0 and root then
            local pos = root.Position
            local dist = (myPos - pos).Magnitude
            local nameLower = obj.Name:lower()

            -- Ignore Ancient Spirits (adds that do not need to be killed)
            if nameLower:find("spirit") then return end

            local isBoss, _ = isBossTarget(obj, hum, root)
            if isBoss and nameLower:find("dragon") and (currentWp and currentWp < 980) then
                return -- Ignore Dragon in mob scan while clearing corridor / stairs!
            end

            table.insert(enemies, {
                model = obj,
                hum = hum,
                root = root,
                pos = pos,
                dist = dist,
                isBoss = isBoss
            })
        end
    end

    local enemiesFolder = Workspace:FindFirstChild("enemies")
    if enemiesFolder then
        for _, c in ipairs(enemiesFolder:GetChildren()) do checkModel(c) end
    end

    local dungeon = Workspace:FindFirstChild("dungeon")
    if dungeon then
        for _, room in ipairs(dungeon:GetChildren()) do
            local eFold = room:FindFirstChild("enemyFolder") or room:FindFirstChild("enemies")
            if eFold then
                for _, c in ipairs(eFold:GetChildren()) do checkModel(c) end
            end
            for _, c in ipairs(room:GetChildren()) do checkModel(c) end
        end
    end

    for _, c in ipairs(Workspace:GetChildren()) do
        if c:IsA("Model") and c ~= myChar then
            checkModel(c)
        end
    end

    table.sort(enemies, function(a, b)
        if a.isBoss and not b.isBoss then return true end
        if not a.isBoss and b.isBoss then return false end
        return a.dist < b.dist
    end)

    return enemies, myPos
end

local function getTargetGroup(enemies, myPos)
    if #enemies == 0 then return nil end

    local primaryEnemy = nil
    for _, e in ipairs(enemies) do
        if e.isBoss or hasLineOfSight(myPos, e.pos, e.isBoss) then
            primaryEnemy = e
            break
        end
    end

    if not primaryEnemy then return nil end

    local group = { primaryEnemy }
    local maxDistInGroup = primaryEnemy.dist
    local farthestEnemy = primaryEnemy

    for i = 1, #enemies do
        local e = enemies[i]
        if e ~= primaryEnemy and (e.pos - primaryEnemy.pos).Magnitude <= 50.0 then
            table.insert(group, e)
            if e.dist > maxDistInGroup then
                maxDistInGroup = e.dist
                farthestEnemy = e
            end
        end
    end

    local sumPos = Vector3.zero
    for _, e in ipairs(group) do sumPos = sumPos + e.pos end
    local groupCenter = sumPos / #group

    return {
        mobs = group,
        count = #group,
        primaryEnemy = primaryEnemy,
        frontMob = primaryEnemy,
        farthestEnemy = farthestEnemy,
        center = groupCenter,
        nearestDist = primaryEnemy.dist,
        farthestDist = maxDistInGroup,
        isBoss = primaryEnemy.isBoss
    }
end

